const input = $json.body ?? $json;

const jobId = input.jobId || input.job_id;
if (!jobId) throw new Error('FAILURE_CONTEXT_REQUIRED: jobId missing');

const stage = input.stage || input.current_step || $json.sourceStage || 'unknown';
const error = input.error || input.message || 'Video generation could not be completed.';
const errorCode = input.errorCode || input.code || input.last_error || 'VIDEO_GENERATION_FAILED';
const currentStep = input.currentStep || input.current_step || 'failed';
const progress = input.progress !== undefined ? input.progress : (input.metadata?.progress ?? 0);

const isFenced = (
  input.workerId != null &&
  input.leaseToken != null &&
  input.pipelineRevision != null
);

const idempotencyKey = input.idempotencyKey ||
  (input.executionId ? `${jobId}:${input.executionId}` : `${jobId}:${stage}:${input.attempt || input.attemptNumber || 0}`);

const safeMetadata = {
  attempt: input.attempt || input.attemptNumber,
  maximum_attempts: input.maximumAttempts || input.max_attempts,
  actual_words: input.metadata?.actual_words || input.actualWords,
  target_words: input.metadata?.target_words || input.targetWords,
  minimum_words: input.metadata?.minimum_words || input.minimumWords,
  maximum_words: input.metadata?.maximum_words || input.maximumWords,
  measured_duration: input.metadata?.measured_duration || input.measuredDuration,
  minimum_duration: input.metadata?.minimum_duration || input.minimumDuration,
  maximum_duration: input.metadata?.maximum_duration || input.maximumDuration,
  current: input.metadata?.current,
  total: input.metadata?.total,
  provider: input.provider || input.providerName,
  workflow: input.workflow || input.workflowName,
  execution_id: input.executionId || input.execution_id,
  node: input.nodeName || input.node
};

const clean = Object.fromEntries(
  Object.entries(safeMetadata).filter(([k, v]) => v !== undefined && v !== null)
);

return [{ json: {
  jobId,
  job_id: jobId,
  stage,
  error,
  errorCode,
  currentStep,
  progress,
  isFenced,
  idempotencyKey,
  metadata: clean,
  workerId: input.workerId,
  leaseToken: input.leaseToken,
  attemptNumber: input.attemptNumber,
  pipelineRevision: input.pipelineRevision,
  stageRunId: input.stageRunId,
  runToken: input.runToken,
  failureClass: input.failureClass,
  retryable: input.retryable,
  error: input.error ?? 'Stage failed',
  failureClass: input.failureClass ?? 'runtime',
  retryable: input.retryable === true
} }];
